                //    type: "string", label: that.globals.BAR_Typ_Inst == Interface.SrvTypIntalaceEnum.MO ? "Číslo pol. plánu od-do" : "Číslo akce od-do", name: "cislo", pathInModel: "cislo",
                //    customOptFieldStart: Eko.Detail.Field.getCounterOptions(that.globals.Delka_Akce!, true, true),
                //    customOptFieldEnd: Eko.Detail.Field.getCounterOptions(that.globals.Delka_Akce!, true, true),
                //    customOptAll: {

                //        change: function (ev, changeObj) {
