                    //name: "aktivita", multi: true, list: true, itemWidth: ""/*, verticalButtons: true*/, serverFilters: { aktivita: [100, 300, 500] }, initialValue: [{ aktivita: Interface.AktivitaAkceEnum.Aktivni }, { aktivita: Interface.AktivitaAkceEnum.Navrh }]
